/** Registers the decorated method as the handler of `name`. */
export declare function OnMessage(name: string): MethodDecorator;
/** Registers the decorated method as the handler of the name its argument infers; `string` when none does. */
export declare const OnEvent: <T = string>(message: T) => MethodDecorator;
/** The same shape with no default: the argument's type is nothing the declaration says. */
export declare function OnNothing<T>(message: T): MethodDecorator;
/** Records the decorated method for tracing; sends and receives nothing. */
export declare function Traced(label: string): MethodDecorator;
/** Marks a class whose decorated methods handle messages. */
export declare function Gateway(): ClassDecorator;
/** Hands the decorated parameter the connection a message came on. */
export declare function Peer(): ParameterDecorator;

export interface Connection {
  id: string;
}

/** A client's connection to a gateway. */
export declare class Link {
  constructor(url: string);
  send(name: string, body: unknown): void;
}
